/* ============================================================================
M2.2 Program 143 v0.2R2 — Positive Validation
120 independent controls. Read-only against business outputs; persists only
validation evidence and lifecycle state. Filterable result survives COMMIT.
============================================================================ */
BEGIN; SET LOCAL work_mem='96MB'; SET LOCAL statement_timeout='45min'; SET LOCAL jit=off;
DROP TABLE IF EXISTS _m2_2_validation;
CREATE TEMP TABLE _m2_2_validation(evidence_code text PRIMARY KEY,metric_name text NOT NULL,observed_value text,threshold_value text,status text NOT NULL,interpretation text NOT NULL) ON COMMIT PRESERVE ROWS;
DROP TABLE IF EXISTS _m2_2_vctx;
CREATE TEMP TABLE _m2_2_vctx ON COMMIT DROP AS SELECT r.run_id,r.run_status,p.* FROM msbf_ctl.run_registry r CROSS JOIN msbf_ctl.m2_2_policy_profile p WHERE r.run_code='M1_V0_2_BASELINE_BUILD' AND r.run_version=1 AND p.policy_code='M2_2_PRICING_STRUCTURE_POLICY_V1';
DO $$ BEGIN PERFORM msbf_ctl.m2_2_assert_validation_ready((SELECT run_id FROM _m2_2_vctx)); END $$;
CREATE OR REPLACE FUNCTION pg_temp.m2_2_add_check(p_code text,p_name text,p_observed text,p_threshold text,p_pass boolean,p_interpretation text) RETURNS void LANGUAGE plpgsql AS $function$ BEGIN INSERT INTO _m2_2_validation VALUES(p_code,p_name,p_observed,p_threshold,CASE WHEN p_pass THEN 'PASS' ELSE 'FAIL' END,p_interpretation); END; $function$;
DO $$ BEGIN
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_001_RUN_STATUS','RUN_STATUS',coalesce(((SELECT run_status FROM _m2_2_vctx))::text,'<NULL>'),'M2_2_GENERATED',coalesce(((SELECT run_status='M2_2_GENERATED' FROM _m2_2_vctx)),FALSE),'Validation begins from committed generated state.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_002_CONTRACT_STATUS','CONTRACT_STATUS',coalesce(((SELECT contract_status FROM msbf_ctl.m2_2_pricing_structure_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'GENERATED',coalesce(((SELECT contract_status='GENERATED' FROM msbf_ctl.m2_2_pricing_structure_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Contract registry is generated.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_003_POLICY_STATUS','POLICY_STATUS',coalesce(((SELECT policy_status FROM _m2_2_vctx))::text,'<NULL>'),'APPROVED',coalesce(((SELECT policy_status='APPROVED' FROM _m2_2_vctx)),FALSE),'Policy is approved.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_004_METHODOLOGY','METHODOLOGY',coalesce(((SELECT methodology_version FROM _m2_2_vctx))::text,'<NULL>'),'M2_2_METHOD_V1',coalesce(((SELECT methodology_version='M2_2_METHOD_V1' FROM _m2_2_vctx)),FALSE),'Methodology identity is exact.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_005_REQUEST_CONTRACT','REQUEST_CONTRACT',coalesce(((SELECT request_contract_code||'|'||request_schema_version FROM _m2_2_vctx))::text,'<NULL>'),'M2_REQUEST_STRUCTURE_CONSUMPTION|M2_2_REQUEST_STRUCTURE_SCHEMA_V1',coalesce(((SELECT request_contract_code='M2_REQUEST_STRUCTURE_CONSUMPTION' AND request_schema_version='M2_2_REQUEST_STRUCTURE_SCHEMA_V1' FROM _m2_2_vctx)),FALSE),'Request contract identity is exact.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_006_PRICING_CONTRACT','PRICING_CONTRACT',coalesce(((SELECT pricing_contract_code||'|'||pricing_schema_version FROM _m2_2_vctx))::text,'<NULL>'),'M2_PRICING_STRUCTURE_CONSUMPTION|M2_2_PRICING_STRUCTURE_SCHEMA_V1',coalesce(((SELECT pricing_contract_code='M2_PRICING_STRUCTURE_CONSUMPTION' AND pricing_schema_version='M2_2_PRICING_STRUCTURE_SCHEMA_V1' FROM _m2_2_vctx)),FALSE),'Pricing contract identity is exact.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_007_M2_1_SOURCE_HASH','M2_1_SOURCE_HASH',coalesce(((SELECT source_m2_1_combined_hash FROM msbf_ctl.m2_2_pricing_structure_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'e5ace7f32060ffb191c7bd0f8dd0c863',coalesce(((SELECT source_m2_1_combined_hash='e5ace7f32060ffb191c7bd0f8dd0c863' FROM msbf_ctl.m2_2_pricing_structure_contract_registry WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Accepted M2.1 combined hash is preserved.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_008_M2_1_GATE','M2_1_GATE',coalesce(((SELECT result_status FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND gate_id='M2_1_ELIGIBILITY_POLICY_ROUTING' ORDER BY review_version DESC LIMIT 1))::text,'<NULL>'),'PASS',coalesce(((SELECT result_status='PASS' FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND gate_id='M2_1_ELIGIBILITY_POLICY_ROUTING' ORDER BY review_version DESC LIMIT 1)),FALSE),'M2.1 acceptance gate is passing.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_009_M1_3_GATE','M1_3_GATE',coalesce(((SELECT result_status FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND gate_id='M1_3_APPLICATION_REQUEST' ORDER BY review_version DESC LIMIT 1))::text,'<NULL>'),'PASS',coalesce(((SELECT result_status='PASS' FROM msbf_ctl.acceptance_gate_result WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND gate_id='M1_3_APPLICATION_REQUEST' ORDER BY review_version DESC LIMIT 1)),FALSE),'M1.3 application/request gate is passing.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_010_CONFIG_HASH_SHAPE','CONFIG_HASH_SHAPE',coalesce(((SELECT configuration_hash FROM _m2_2_vctx))::text,'<NULL>'),'32 lowercase hex',coalesce(((SELECT length(configuration_hash)=32 AND configuration_hash ~ '^[0-9a-f]+$' FROM _m2_2_vctx)),FALSE),'Configuration hash shape is valid.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_011_CONFIG_HASH_IDENTITY','CONFIG_HASH_IDENTITY',coalesce(((SELECT configuration_hash FROM _m2_2_vctx))::text,'<NULL>'),'payload hash',coalesce(((SELECT configuration_hash=msbf_ctl.m2_2_hash_jsonb(configuration_payload) FROM _m2_2_vctx)),FALSE),'Configuration hash reconstructs from payload.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_012_BOUNDARY_FLAGS','BOUNDARY_FLAGS',coalesce(((SELECT concat_ws('|',synthetic_data_only_flag,counteroffer_foundation_only_flag,no_final_credit_decision_flag,no_production_adverse_action_flag,no_booking_funding_flag,acquisition_source_noncredit_flag,stress_nonimprovement_flag,request_companion_required_flag) FROM _m2_2_vctx))::text,'<NULL>'),'true|true|true|true|true|true|true|true',coalesce(((SELECT synthetic_data_only_flag AND counteroffer_foundation_only_flag AND no_final_credit_decision_flag AND no_production_adverse_action_flag AND no_booking_funding_flag AND acquisition_source_noncredit_flag AND stress_nonimprovement_flag AND request_companion_required_flag FROM _m2_2_vctx)),FALSE),'All stage-boundary flags remain approved.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_013_EXPECTED_COUNTS','EXPECTED_COUNTS',coalesce(((SELECT concat_ws('|',expected_candidate_rows,expected_pricing_snapshot_rows,expected_canonical_entities,expected_positive_controls,expected_negative_controls) FROM _m2_2_vctx))::text,'<NULL>'),'557|1500|7336|120|20',coalesce(((SELECT expected_candidate_rows=557 AND expected_pricing_snapshot_rows=1500 AND expected_canonical_entities=7336 AND expected_positive_controls=120 AND expected_negative_controls=20 FROM _m2_2_vctx)),FALSE),'Frozen expected counts are exact.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_014_REFERENCE_COUNTS','REFERENCE_COUNTS',coalesce((SELECT concat_ws('|',(SELECT count(*) FROM msbf_m2.pricing_structure_candidate_template WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)),(SELECT count(*) FROM msbf_m2.pricing_structure_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)),(SELECT count(*) FROM msbf_m2.pricing_structure_disposition_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))))::text,'<NULL>'),'5|18|4',coalesce((SELECT (SELECT count(*) FROM msbf_m2.pricing_structure_candidate_template WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))=5 AND (SELECT count(*) FROM msbf_m2.pricing_structure_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))=18 AND (SELECT count(*) FROM msbf_m2.pricing_structure_disposition_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))=4),FALSE),'Reference dictionaries are complete.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_015_GENERATION_EVIDENCE','GENERATION_EVIDENCE',coalesce(((SELECT count(*) FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND evidence_code LIKE 'M2_2_%' AND evidence_code NOT LIKE 'M2_2_POS_%' AND evidence_code NOT LIKE 'M2_2_NEG_%' AND evidence_code<>'M2_2_ACCEPTANCE_SUMMARY'))::text,'<NULL>'),'20',coalesce(((SELECT count(*)=20 FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND evidence_code LIKE 'M2_2_%' AND evidence_code NOT LIKE 'M2_2_POS_%' AND evidence_code NOT LIKE 'M2_2_NEG_%' AND evidence_code<>'M2_2_ACCEPTANCE_SUMMARY')),FALSE),'Generation evidence inventory is exact.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_016_REQUIRED_TABLES','REQUIRED_TABLES',coalesce(((SELECT count(*) FROM unnest(ARRAY['msbf_ctl.m2_2_policy_profile','msbf_ctl.m2_2_pricing_structure_contract_registry','msbf_m2.pricing_structure_candidate_template','msbf_m2.pricing_structure_reason_definition','msbf_m2.pricing_structure_disposition_definition','msbf_m2.application_request_structure_snapshot','msbf_m2.application_request_structure_latest','msbf_m2.application_request_structure_archive','msbf_m2.application_pricing_structure_candidate','msbf_m2.application_pricing_structure_snapshot','msbf_m2.application_pricing_structure_latest','msbf_m2.application_pricing_structure_archive']) x WHERE to_regclass(x) IS NOT NULL))::text,'<NULL>'),'12',coalesce(((SELECT count(*)=12 FROM unnest(ARRAY['msbf_ctl.m2_2_policy_profile','msbf_ctl.m2_2_pricing_structure_contract_registry','msbf_m2.pricing_structure_candidate_template','msbf_m2.pricing_structure_reason_definition','msbf_m2.pricing_structure_disposition_definition','msbf_m2.application_request_structure_snapshot','msbf_m2.application_request_structure_latest','msbf_m2.application_request_structure_archive','msbf_m2.application_pricing_structure_candidate','msbf_m2.application_pricing_structure_snapshot','msbf_m2.application_pricing_structure_latest','msbf_m2.application_pricing_structure_archive']) x WHERE to_regclass(x) IS NOT NULL)),FALSE),'All required tables exist.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_017_REQUIRED_VIEWS','REQUIRED_VIEWS',coalesce(((SELECT count(*) FROM unnest(ARRAY['msbf_m2.v_m2_2_request_structure_latest','msbf_m2.v_m2_2_pricing_structure_latest','msbf_m2.v_m2_2_candidate_detail','msbf_m2.v_m2_2_matched_scenario_comparison','msbf_ctl.v_m2_2_lineage','msbf_m2.v_m2_2_power_bi_pricing_structure']) x WHERE to_regclass(x) IS NOT NULL))::text,'<NULL>'),'6',coalesce(((SELECT count(*)=6 FROM unnest(ARRAY['msbf_m2.v_m2_2_request_structure_latest','msbf_m2.v_m2_2_pricing_structure_latest','msbf_m2.v_m2_2_candidate_detail','msbf_m2.v_m2_2_matched_scenario_comparison','msbf_ctl.v_m2_2_lineage','msbf_m2.v_m2_2_power_bi_pricing_structure']) x WHERE to_regclass(x) IS NOT NULL)),FALSE),'All governed views exist.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_018_ARCHIVE_TRIGGERS','ARCHIVE_TRIGGERS',coalesce(((SELECT count(*) FROM pg_trigger WHERE tgname IN('trg_m2_2_request_archive_immutable','trg_m2_2_pricing_archive_immutable') AND NOT tgisinternal))::text,'<NULL>'),'2',coalesce(((SELECT count(*)=2 FROM pg_trigger WHERE tgname IN('trg_m2_2_request_archive_immutable','trg_m2_2_pricing_archive_immutable') AND NOT tgisinternal)),FALSE),'Both archives are immutable.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_019_GATE_DEFINITION','ACCEPTANCE_GATE_DEFINITION',coalesce(((SELECT count(*) FROM msbf_ref.acceptance_gate_catalog WHERE gate_id='M2_2_PRICING_STRUCTURE_COUNTEROFFER' AND active_flag))::text,'<NULL>'),'1',coalesce(((SELECT count(*)=1 FROM msbf_ref.acceptance_gate_catalog WHERE gate_id='M2_2_PRICING_STRUCTURE_COUNTEROFFER' AND active_flag)),FALSE),'Acceptance gate definition exists.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_020_POLICY_ROW','POLICY_ROW',coalesce(((SELECT count(*) FROM msbf_ctl.m2_2_policy_profile WHERE policy_code='M2_2_PRICING_STRUCTURE_POLICY_V1'))::text,'<NULL>'),'1',coalesce(((SELECT count(*)=1 FROM msbf_ctl.m2_2_policy_profile WHERE policy_code='M2_2_PRICING_STRUCTURE_POLICY_V1')),FALSE),'Exactly one policy row exists.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_021_TEMPLATE_UNIQUE_GRAIN','TEMPLATE_UNIQUE_GRAIN',coalesce(((SELECT count(*)-count(DISTINCT candidate_template_code) FROM msbf_m2.pricing_structure_candidate_template WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=count(DISTINCT candidate_template_code) FROM msbf_m2.pricing_structure_candidate_template WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Template grain is unique.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_022_REASON_UNIQUE_GRAIN','REASON_UNIQUE_GRAIN',coalesce(((SELECT count(*)-count(DISTINCT reason_code) FROM msbf_m2.pricing_structure_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=count(DISTINCT reason_code) FROM msbf_m2.pricing_structure_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Reason grain is unique.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_023_DISPOSITION_UNIQUE_GRAIN','DISPOSITION_UNIQUE_GRAIN',coalesce(((SELECT count(*)-count(DISTINCT disposition_code) FROM msbf_m2.pricing_structure_disposition_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=count(DISTINCT disposition_code) FROM msbf_m2.pricing_structure_disposition_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Disposition grain is unique.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_024_NO_FINAL_DECISION_COLUMNS','NO_FINAL_DECISION_COLUMNS',coalesce(((SELECT count(*) FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN('application_request_structure_snapshot','application_request_structure_latest','application_request_structure_archive','application_pricing_structure_candidate','application_pricing_structure_snapshot','application_pricing_structure_latest','application_pricing_structure_archive') AND lower(column_name) IN('approval_flag','decline_flag','final_decision_code','adverse_action_code','booking_status','funding_status')))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM information_schema.columns WHERE table_schema='msbf_m2' AND table_name IN('application_request_structure_snapshot','application_request_structure_latest','application_request_structure_archive','application_pricing_structure_candidate','application_pricing_structure_snapshot','application_pricing_structure_latest','application_pricing_structure_archive') AND lower(column_name) IN('approval_flag','decline_flag','final_decision_code','adverse_action_code','booking_status','funding_status'))),FALSE),'No final decision, adverse action, booking or funding fields exist.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_025_PRODUCTION_REASON_FLAGS','PRODUCTION_REASON_FLAGS',coalesce(((SELECT count(*) FROM msbf_m2.pricing_structure_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND production_adverse_action_flag))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.pricing_structure_reason_definition WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND production_adverse_action_flag)),FALSE),'No reason is approved for production adverse action.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_026_REQUEST_SNAPSHOT_ROWS','REQUEST_SNAPSHOT_ROWS',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'750',coalesce(((SELECT count(*)=750 FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Request Snapshot Rows.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_027_REQUEST_LATEST_ROWS','REQUEST_LATEST_ROWS',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_latest WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'750',coalesce(((SELECT count(*)=750 FROM msbf_m2.application_request_structure_latest WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Request Latest Rows.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_028_REQUEST_ARCHIVE_ROWS','REQUEST_ARCHIVE_ROWS',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_archive WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'750',coalesce(((SELECT count(*)=750 FROM msbf_m2.application_request_structure_archive WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Request Archive Rows.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_029_REQUEST_APPLICATIONS','REQUEST_APPLICATIONS',coalesce(((SELECT count(DISTINCT merchant_application_id) FROM msbf_m2.application_request_structure_latest WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'750',coalesce(((SELECT count(DISTINCT merchant_application_id)=750 FROM msbf_m2.application_request_structure_latest WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Request Applications.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_030_REQUEST_UNIQUE_GRAIN','REQUEST_UNIQUE_GRAIN',coalesce(((SELECT count(*)-count(DISTINCT merchant_application_id) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx)))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=count(DISTINCT merchant_application_id) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx))),FALSE),'Request snapshot grain is unique.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_031_REQUEST_SOURCE_RECONCILIATION','REQUEST_SOURCE_RECONCILIATION',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot s FULL OUTER JOIN msbf_m1.merchant_application a ON a.merchant_application_id=s.merchant_application_id WHERE coalesce(s.module1_run_id,a.created_by_run_id)=(SELECT run_id FROM _m2_2_vctx) AND (s.merchant_application_id IS NULL OR a.merchant_application_id IS NULL OR s.source_request_hash IS DISTINCT FROM a.request_hash OR s.requested_funding_amount IS DISTINCT FROM a.requested_funding_amount OR s.requested_remittance_rate IS DISTINCT FROM a.requested_remittance_rate)))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_request_structure_snapshot s FULL OUTER JOIN msbf_m1.merchant_application a ON a.merchant_application_id=s.merchant_application_id WHERE coalesce(s.module1_run_id,a.created_by_run_id)=(SELECT run_id FROM _m2_2_vctx) AND (s.merchant_application_id IS NULL OR a.merchant_application_id IS NULL OR s.source_request_hash IS DISTINCT FROM a.request_hash OR s.requested_funding_amount IS DISTINCT FROM a.requested_funding_amount OR s.requested_remittance_rate IS DISTINCT FROM a.requested_remittance_rate))),FALSE),'Request snapshot reproduces M1.3 physical request data.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_032_REQUEST_AMOUNT_POSITIVE','REQUEST_AMOUNT_POSITIVE',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_funding_amount<=0))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_funding_amount<=0)),FALSE),'Requested amount is positive.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_033_REQUEST_RATE_DOMAIN','REQUEST_RATE_DOMAIN',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_remittance_rate NOT BETWEEN 0 AND 1))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_remittance_rate NOT BETWEEN 0 AND 1)),FALSE),'Requested remittance is in domain.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_034_REQUEST_HORIZON_DOMAIN','REQUEST_HORIZON_DOMAIN',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_expected_payoff_days NOT IN(30,60,90)))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_expected_payoff_days NOT IN(30,60,90))),FALSE),'Requested horizon is in governed source domain.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_035_REQUEST_REPAYMENT_IDENTITY','REQUEST_REPAYMENT_IDENTITY',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_total_repayment_amount IS DISTINCT FROM requested_funding_amount+requested_finance_charge_amount))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND requested_total_repayment_amount IS DISTINCT FROM requested_funding_amount+requested_finance_charge_amount)),FALSE),'Requested repayment identity reconciles.');
    PERFORM pg_temp.m2_2_add_check('M2_2_POS_036_REQUEST_PAYBACK_IDENTITY','REQUEST_PAYBACK_IDENTITY',coalesce(((SELECT count(*) FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND abs(requested_payback_multiple-(requested_total_repayment_amount/requested_funding_amount))>0.000001))::text,'<NULL>'),'0',coalesce(((SELECT count(*)=0 FROM msbf_m2.application_request_structure_snapshot WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx) AND abs(requested_payback_multiple-(requested_total_repayment_amount/requested_funding_amount))>0.000001)),FALSE),'Requested payback multiple reconciles.');
