END $$;
DO $$ DECLARE v_total bigint; v_pass bigint; v_fail bigint; BEGIN
 SELECT count(*),count(*) FILTER(WHERE status='PASS'),count(*) FILTER(WHERE status='FAIL') INTO v_total,v_pass,v_fail FROM _m2_2_validation;
 IF v_total<>120 THEN RAISE EXCEPTION 'M2.2 positive-control inventory failed: %.',v_total; END IF;
 DELETE FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM _m2_2_vctx) AND evidence_code LIKE 'M2_2_POS_%';
 INSERT INTO msbf_ctl.run_evidence(run_id,evidence_code,segment_key,metric_name,metric_value_text,unit_code,status,interpretation)
 SELECT (SELECT run_id FROM _m2_2_vctx),evidence_code,'PORTFOLIO',metric_name,observed_value,'VALIDATION',status,interpretation||' Threshold: '||threshold_value FROM _m2_2_validation;
 IF v_pass=120 AND v_fail=0 THEN
  UPDATE msbf_ctl.run_registry SET run_status='M2_2_VALIDATED' WHERE run_id=(SELECT run_id FROM _m2_2_vctx);
  UPDATE msbf_ctl.m2_2_pricing_structure_contract_registry SET contract_status='VALIDATED',validated_at=clock_timestamp() WHERE module1_run_id=(SELECT run_id FROM _m2_2_vctx);
 ELSE
  UPDATE msbf_ctl.run_registry SET run_status='M2_2_FAILED' WHERE run_id=(SELECT run_id FROM _m2_2_vctx);
 END IF;
END $$;
COMMIT;
SELECT evidence_code,metric_name,observed_value,threshold_value,status,interpretation FROM _m2_2_validation ORDER BY evidence_code;
